export const documentSuggestions = query({args:{...authArgs,id:documentId},returns:v.string(),handler:async(ctx,args)=>{
 const access=await member(ctx,args,"documents"),document=await ctx.db.get(args.id);if(!document)throw new ConvexError("Document missing");requireScope(access,document);
 const details=extractedDetails(document.extracted),amount=typeof details.amount==="string"&&typeof details.currency==="string"?statementAmountMinor(details.amount,details.currency):undefined;
 const policies=(await Promise.all(access.companyIds.map(companyId=>ctx.db.query("statementPolicies").withIndex("by_company",q=>q.eq("companyId",companyId)).take(100)))).flat().filter(p=>canReadScope(access,p));
 const source=[document.sender,document.subject].filter(Boolean).join(" ").toLowerCase();
 const routing=policies.filter(p=>String(JSON.parse(p.settingsJson).inboxKeywords??"").split("\n").some(word=>word.trim().length>=3&&source.includes(word.trim().toLowerCase()))).map(p=>({companyId:p.companyId,financialAccountId:p.financialAccountId,reason:"Configured inbox keyword matched; manual verification required"}));
 const candidates=(await Promise.all((document.companyId?[document.companyId]:access.companyIds).map(companyId=>ctx.db.query("statementTransactions").withIndex("by_companyId_and_date",q=>q.eq("companyId",companyId)).order("desc").take(500)))).flat().filter(r=>canReadScope(access,r)&&!r.deletedAt&&r.status!=="completed"&&(!document.financialAccountId||r.financialAccountId===document.financialAccountId));
 const matches=candidates.map(r=>({id:r._id,date:r.date,description:r.description,companyId:r.companyId,financialAccountId:r.financialAccountId,amountMinor:r.amountMinor,currency:r.currency,score:(amount&&r.amountMinor===amount&&r.currency===details.currency?2:0)+(typeof details.reference==="string"&&details.reference&&r.reference===details.reference?4:0)+(typeof details.counterparty==="string"&&r.counterparty?.toLowerCase()===details.counterparty.toLowerCase()?1:0)})).filter(r=>r.score>=2).sort((a,b)=>b.score-a.score).slice(0,5);
 return JSON.stringify({routing,matches,automaticLink:false});
}});
